# Read input
n, k = map(int, input().split())
d = list(map(int, input().split()))

# Count remainders
from collections import Counter
remainders = Counter()
for num in d:
    remainders[num % k] += 1

# Calculate maximum number of gifts
gifts = 0

# Handle remainder 0 separately
if remainders[0] % 2 == 0:
    gifts += remainders[0] // 2
else:
    gifts += (remainders[0] - 1) // 2

# Handle other remainders
for i in range(1, k // 2 + 1):
    if i != k - i:
        if remainders[i] < remainders[k - i]:
            gifts += remainders[i]
        else:
            gifts += remainders[k - i]
    else:  # i == k - i (when k is even)
        gifts += remainders[i] // 2

print(gifts * 2)
"}

