def count_prime_factor(n, p):
    count = 0
    power = p
    while power <= n:
        count += n // power
        power *= p
    return count


def factorize(b):
    factors = {}
    # Check for even factors
    while b % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        b //= 2
    # Check for odd factors
    i = 3
    while i * i <= b:
        while b % i == 0:
            factors[i] = factors.get(i, 0) + 1
            b //= i
        i += 2
    # If remaining b is a prime > 2
    if b > 1:
        factors[b] = factors.get(b, 0) + 1
    return factors


def solve(n, b):
    factors = factorize(b)
    if not factors:
        return 0  # b is 1, but b >= 2

    min_ratio = float('inf')
    for p, e in factors.items():
        count_p = count_prime_factor(n, p)
        ratio = count_p / e
        if ratio < min_ratio:
            min_ratio = ratio

    return int(min_ratio)


# Read input
n, b = map(int, input().split())

# Solve and print
print(solve(n, b))
"}

