import itertools

def is_palindrome(s):
    return s == s[::-1]

def solve():
    s = input().strip()

    # If all characters are the same, impossible
    if len(set(s)) == 1:
        print("Impossible")
        return

    n = len(s)

    # Try with 1 cut
    for i in range(1, n):
        part1 = s[:i]
        part2 = s[i:]

        # Check if we can rearrange to get a different palindrome
        for perm in itertools.permutations([part1, part2]):
            new_str = perm[0] + perm[1]
            if new_str != s and is_palindrome(new_str):
                print(1)
                return

    # If 1 cut doesn't work, try with 2 cuts
    for i in range(1, n):
        for j in range(i + 1, n):
            part1 = s[:i]
            part2 = s[i:j]
            part3 = s[j:]

            # Check if we can rearrange to get a different palindrome
            for perm in itertools.permutations([part1, part2, part3]):
                new_str = perm[0] + perm[1] + perm[2]
                if new_str != s and is_palindrome(new_str):
                    print(2)
                    return

    print("Impossible")

solve()
"}

