def main():
    # Read input
    n, a, b, c = map(int, input().split())

    # Initialize DP array
    dp = [-1] * (n + 1)  # -1 means not possible
    dp[0] = 0  # Base case: 0 length has 0 pieces

    for length in range(1, n + 1):
        for cut_length in [a, b, c]:
            if length >= cut_length and dp[length - cut_length] != -1:
                dp[length] = max(dp[length], dp[length - cut_length] + 1)

    print(dp[n])

if __name__ == "__main__":
    main()
