def solve():
    t = int(input())
    for _ in range(t):
        n, s = map(int, input().split())
        a = list(map(int, input().split()))
        total = sum(a)

        if total <= s:
            print(0)
            continue

        # Find which part to skip
        max_parts = 0
        best_idx = -1

        # Try skipping each part
        for i in range(n):
            # Calculate total time if we skip part i
            total_without_i = total - a[i]

            # If total time without part i is within limit, we can recite all but one
            if total_without_i <= s:
                if max_parts < n-1:
                    max_parts = n-1
                    best_idx = i + 1  # 1-indexed
            else:
                # Calculate how many parts we can recite if we skip part i
                time = 0
                count = 0

                # Recite parts in sequence, skipping part i
                for j in range(n):
                    if j == i:
                        continue
                    if time + a[j] > s:
                        break
                    time += a[j]
                    count += 1

                if count > max_parts:
                    max_parts = count
                    best_idx = i + 1  # 1-indexed

        print(best_idx)

solve()
