            for j in range(n - 1, 0, -1):
                mat[0][j] = val
                val += 1
            # Fill row 1 from right to left, starting with n²-1
            for j in range(n - 1, 0, -1):
                mat[1][j] = val
                val += 1
            # Fill row 2 from left to right
            for j in range(n):
                mat[2][j] = val
                val += 1
            # Print the matrix
            for row in mat:
                print(' '.join(map(str, row)))

