def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    idx = 0
    n = int(data[idx])
    m = int(data[idx+1])
    idx += 2

    a = list(map(int, data[idx:idx+n]))
    idx += n

    # Precompute for each position: next equal to the right, previous equal to the left
    next_eq = [-1] * n
    last = {}
    for i in range(n):
        if a[i] in last:
            next_eq[i] = last[a[i]]
        last[a[i]] = i

    prev_eq = [-1] * n
    last = {}
    for i in range(n):
        if a[i] in last:
            prev_eq[i] = last[a[i]]
        last[a[i]] = i

    output = []
    for _ in range(m):
        l = int(data[idx]) - 1  # 0-indexed
        r = int(data[idx+1]) - 1
        idx += 2

        min_dist = float('inf')

        # Check next equal to the right
        if next_eq[l] != -1 and next_eq[l] <= r:
            min_dist = min(min_dist, next_eq[l] - l)

        # Check previous equal to the left
        if prev_eq[r] != -1 and prev_eq[r] >= l:
            min_dist = min(min_dist, r - prev_eq[r])

        if min_dist == float('inf'):
            output.append("-1")
        else:
            output.append(str(min_dist))

    sys.stdout.write("\n".join(output))

solve()
