def count_ac(s):
    """Count occurrences of "AC" in string s"""
    count = 0
    for i in range(len(s) - 1):
        if s[i] == 'A' and s[i+1] == 'C':
            count += 1
    return count

# Read input
k, x, n, m = map(int, input().split())

# Try brute force for s1 and s2
def solve():
    # Try all combinations for s1 (length n)
    for s1 in product(string.ascii_uppercase, repeat=n):
        # Count AC in s1
        ac1 = count_ac(s1)
        # If s1 ends with 'A', count occurrences of 'C' after the last 'A'
        last_a_pos = -1
        for i, c in enumerate(s1):
            if c == 'A':
                last_a_pos = i
        cross1 = 0
        if last_a_pos != -1:
            for i in range(last_a_pos+1, n):
                if s1[i] == 'C':
                    cross1 += 1

        # Try all combinations for s2 (length m)
        for s2 in product(string.ascii_uppercase, repeat=m):
            ac2 = count_ac(s2)
            # If s2 starts with 'C', count occurrences of 'A' before the first 'C'
            first_c_pos = -1
            for i, c in enumerate(s2):
                if c == 'C':
                    first_c_pos = i
                    break
            cross2 = 0
            if first_c_pos != -1:
                for i in range(first_c_pos):
                    if s2[i] == 'A':
                        cross2 += 1

            # Count AC across boundary
            cross = 0
            if last_a_pos != -1 and s2[0] == 'C':
                cross = 1

            # Total AC
            total_ac = ac1 + ac2 + cross
            if total_ac == x:
                print(''.join(s1))
                print(''.join(s2))
                return
    print("Happy new year!")

