import string

# Helper function to count "AC" occurrences in a string
def count_ac(s):
    """Count occurrences of "AC" in string s"""
    count = 0
    for i in range(len(s) - 1):
        if s[i] == 'A' and s[i+1] == 'C':
            count += 1
    return count

# Read input
