# Try brute force for s1 and s2 with early stopping
# For k=3, s3 = s1 + s2, we need total "AC" = x

def solve():
    # Try all combinations for s1 (length n)
    for s1 in itertools.product(string.ascii_uppercase, repeat=n):
        # Count AC in s1
        ac1 = count_ac(s1)
        # If s1 ends with 'A', count occurrences of 'C' after the last 'A'
        last_a_pos = -1
        for i, c in enumerate(s1):
