                last_a_pos = i
        cross1 = 0
        if last_a_pos != -1:
            for i in range(last_a_pos+1, n):
                if s1[i] == 'C':
                    cross1 += 1

        # If we already have too many AC in s1, skip (optimization)
        if ac1 > x:
            continue

        # Try all combinations for s2 (length m)
        for s2 in itertools.product(string.ascii_uppercase, repeat=m):
            ac2 = count_ac(s2)
            # If s2 starts with 'C', count occurrences of 'A' before the first 'C'
            first_c_pos = -1
            for i, c in enumerate(s2):
                if c == 'C':
                    first_c_pos = i
                    break
            cross2 = 0
            if first_c_pos != -1:
                for i in range(first_c_pos):
                    if s2[i] == 'A':
                        cross2 += 1

            # Count AC across boundary
            cross = 0
            if last_a_pos != -1 and s2[0] == 'C':
                cross = 1

            # Total AC
            total_ac = ac1 + ac2 + cross
            if total_ac == x:
                print(''.join(s1))
