# Build graph
graph = [[] for _ in range(n + 1)]  # graph[house] = list of (next_house, diameter)

for _ in range(p):
    a, b, d = map(int, input().split())
    graph[a].append((b, d))

# Find tanks (outgoing only, no incoming)
tanks = []
for i in range(1, n + 1):
    has_incoming = False
    for a, b, d in graph:
        if b == i:
            has_incoming = True
            break
    has_outgoing = bool(graph[i])
    if not has_incoming and has_outgoing:
        tanks.append(i)

# Find taps (incoming only, no outgoing)
taps = []
for i in range(1, n + 1):
    has_incoming = False
    for a, b, d in graph:
        if b == i:
            has_incoming = True
            break
    has_outgoing = bool(graph[i])
    if has_incoming and not has_outgoing:
        taps.append(i)

# For each tank, trace path to tap and find minimum diameter
results = []
for tank in tanks:
    current = tank
    min_diameter = float('inf')
    while current is not None:
        # Find outgoing pipe
        if graph[current]:
            next_house, diameter = graph[current][0]
            min_diameter = min(min_diameter, diameter)
            current = next_house
        else:
            # No outgoing pipe, this should be a tap
            if not graph[current]:
                # current is a tap
                results.append((tank, current, min_diameter))
            break

# Sort by tank index
results.sort()

# Output
print(len(results))
for tank, tap, d in results:
    print(tank, tap, d)
