import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+n]))
    b = list(map(int, data[2+n:2+2*n]))

    takeoff_product = 1.0
    for i in range(n):
        if a[i] == 1:
            takeoff_product = 0.0
            break
        takeoff_product *= (1.0 - 1.0 / a[i])

    landing_product = 1.0
    for i in range(n):
        if b[i] == 1:
            landing_product = 0.0
            break
        landing_product *= (1.0 - 1.0 / b[i])

    final_product = takeoff_product * landing_product

    if final_product == 0.0:
        print(-1.0)
    elif final_product > 1.0:
        print(0.0)
    else:
        fuel = m / final_product - m
        print(f"{fuel:.10f}")

if __name__ == "__main__":
    solve()
