def solve():
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(input().strip())

    xT, yT = map(int, input().split())
    xM, yM = map(int, input().split())

    # Convert 1-indexed to 0-indexed
    xT -= 1
    yT -= 1
    xM -= 1
    yM -= 1

    # Door directions: 0=up, 1=right, 2=down, 3=left
    # For each character, return the set of directions it has doors
    def get_doors(c, rotations):
        # Rotate the character 'rotations' times
        c = c + '0123456789' * 10  # Ensure it's long enough for rotations
        c = c[rotations % 4]

        if c == '+':
            return {0, 1, 2, 3}
        elif c == '-':
            return {1, 2}  # right and left
        elif c == '|':
            return {0, 2}  # up and down
        elif c == '^':
            return {0}     # up
        elif c == '>':
            return {1}     # right
        elif c == '<':
            return {3}     # left (wait, this is wrong)
        elif c == 'v':
            return {2}     # down
        elif c == 'L':
            return {0, 1, 3}  # up, right, left
        elif c == 'R':
            return {0, 2, 3}  # up, down, left
        elif c == 'U':
            return {1, 2, 3}  # right, down, left
        elif c == 'D':
            return {0, 1, 3}  # up, right, left
        elif c == '*':
            return set()
        else:
            return set()

    # For each block, precompute its doors in all 4 orientations
    doors_in_rotations = []
    for i in range(n):
        row = []
        for j in range(m):
            # Store doors in all 4 rotations
            row.append([set() for _ in range(4)])
            char = grid[i][j]
            for r in range(4):
                row[j][r] = get_doors(char, r)
        doors_in_rotations.append(row)

    # BFS
    from collections import deque

    # (x, y, rotations, time)
    visited = [[[-1 for _ in range(4)] for _ in range(m)] for _ in range(n)]
    q = deque()

    # Start at position (xT, yT) with 0 rotations and time 0
    visited[xT][yT][0] = 0
    q.append((xT, yT, 0, 0))

    while q:
        x, y, r, time = q.popleft()

        # Try to move to neighbors
        for dx, dy, dir in [(-1, 0, 0), (0, 1, 1), (1, 0, 2), (0, -1, 3)]:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m:
                # Check if we can move from (x,y) to (nx, ny)
                # Block (x,y) has door in direction 'dir'
                # Block (nx,ny) has door in direction opposite to 'dir'

                has_door = dir in doors_in_rotations[y][x][r]
                opposite_dir = (dir + 2) % 4  # 0 <-> 2 (up <-> down), 1 <-> 3 (right <-> left)
                other_has_door = opposite_dir in doors_in_rotations[ny][nx][r]

                if has_door and other_has_door:
                    if visited[nx][ny][r] == -1:
                        visited[nx][ny][r] = time + 1
                        q.append((nx, ny, r, time + 1))

        # Try to rotate
        next_r = (r + 1) % 4
        if visited[x][y][next_r] == -1:
            visited[x][y][next_r] = time + 1
            q.append((x, y, next_r, time + 1))

    result = min(visited[xM][yM])
    print(result if result != -1 else -1)

solve()
