        next_r = (r + 1) % 4
        if visited[x][y][next_r] == -1:
            visited[x][y][next_r] = time + 1
            q.append((x, y, next_r, time + 1))

    result = min(visited[xM][yM])
    print(result if result != -1 else -1)

