from collections import defaultdict

split_rules = defaultdict(list)

for _ in range(m):
    parts = list(map(int, input().split()))
    mi = parts[0]
    li = parts[1]
    diamonds_and_monsters = parts[2:]

    diamonds = 0
    monsters = []

    for item in diamonds_and_monsters:
        if item == -1:
            diamonds += 1
        else:
            monsters.append(item)

    split_rules[mi].append((diamonds, monsters))

# DP tables: min_diamonds[i] = minimum diamonds for monster i
# max_diamonds[i] = maximum diamonds for monster i
min_diamonds = [-1] * (n + 1)  # -1 means impossible to guarantee termination
max_diamonds = [-1] * (n + 1)  # -1 means impossible to end without monsters

# Special values:
# -2 = arbitrarily large diamonds
# 314000000 = overflow limit

# Compute min_diamonds using DP
for i in range(1, n + 1):
    if i not in split_rules:
        min_diamonds[i] = -1
        continue

    min_val = float('inf')
    for diamonds, monsters in split_rules[i]:
        total = diamonds
        valid = True
        for monster in monsters:
            if min_diamonds[monster] == -1:
                # Can't guarantee termination
                valid = False
                break
            total += min_diamonds[monster]

        if valid:
            min_val = min(min_val, total)

    if min_val == float('inf'):
        # No valid split found (shouldn't happen as each monster has at least one rule)
        min_diamonds[i] = -1
    else:
        min_diamonds[i] = min_val

    # Check for overflow
    if min_diamonds[i] > 314000000:
        min_diamonds[i] = 314000000

# Compute max_diamonds using DP
for i in range(1, n + 1):
    if i not in split_rules:
        max_diamonds[i] = -1
        continue

    max_val = -float('inf')
    for diamonds, monsters in split_rules[i]:
        total = diamonds
        for monster in monsters:
            if max_diamonds[monster] == -2:
                # Can get arbitrarily large diamonds
                max_val = -2
                break
            total += max_diamonds[monster]

        if max_val != -2:
            max_val = max(max_val, total)

    if max_val == -float('inf'):
        # No valid split found (shouldn't happen)
        max_diamonds[i] = -1
    elif max_val == -2:
        max_diamonds[i] = -2
    else:
        max_diamonds[i] = max_val

    # Check for overflow
    if max_diamonds[i] > 314000000:
        max_diamonds[i] = 314000000

# Print results
for i in range(1, n + 1):
    print(min_diamonds[i], max_diamonds[i])
