def solve():
    a, b, c, d = map(int, input().split())
    total = a + b + c + d

    # Check if it's possible
    max_count = max(a, b, c, d)
    other_sum = total - max_count

    # The condition for beautiful sequence: max_count <= other_sum + 1
    if max_count > other_sum + 1:
        print("NO")
        return

    # Construct the sequence

    # Find which number is most frequent
    if a == max_count:
        # 0 is most frequent
        seq = []
        # Start with 0 and alternate
        for i in range(max_count):
            seq.append(0)
            if i < b and b > 0:
                seq.append(1)

        # Now we need to add the remaining numbers
        # These will go at the end
        remaining = []
        if b > a:
            remaining += [1] * (b - a)
        if c > 0:
            remaining += [2] * c
        if d > 0:
            remaining += [3] * d

        # Add remaining at the end
        seq += remaining
    elif b == max_count:
        # 1 is most frequent
        seq = []
        for i in range(max_count):
            seq.append(1)
            if i < a and a > 0:
                seq.append(0)
            if i < c and c > 0:
                seq.append(2)
    elif c == max_count:
        # 2 is most frequent
        seq = []
        for i in range(max_count):
            seq.append(2)
            if i < b and b > 0:
                seq.append(1)
            if i < d and d > 0:
                seq.append(3)
    else:
        # 3 is most frequent
        seq = []
        for i in range(max_count):
            seq.append(3)
            if i < c and c > 0:
                seq.append(2)

        # Now we need to add the remaining numbers
        # These will go at the beginning
        remaining = []
        if c > d:
            remaining += [2] * (c - d)
        if b > 0:
            remaining += [1] * b
        if a > 0:
            remaining += [0] * a

        # Add remaining at the beginning
        seq = remaining + seq

    # Check if the sequence is beautiful
    valid = True
    for i in range(len(seq) - 1):
        if abs(seq[i] - seq[i+1]) != 1:
            valid = False
            break

    if valid:
        print("YES")
        print(' '.join(map(str, seq)))
    else:
        print("NO")

solve()
