import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = []
    for _ in range(n):
        a.append(int(next(it)))

    # For each value, store its occurrences
    from collections import defaultdict
    value_positions = defaultdict(list)
    for i, val in enumerate(a):
        value_positions[val].append(i)

    # For each position, find previous and next occurrence of the same value
    prev = [-1] * n
    next_pos = [n] * n

    # First pass: find previous occurrence
    for val in value_positions:
        positions = value_positions[val]
        if len(positions) > 1:
            for i in range(1, len(positions)):
                prev[positions[i]] = positions[i-1]

    # Second pass: find next occurrence
    for val in value_positions:
        positions = value_positions[val]
        if len(positions) > 1:
            for i in range(len(positions) - 1):
                next_pos[positions[i]] = positions[i+1]

    # Process queries
    output = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))

        min_distance = float('inf')

        # Check each position in the range [l, r-1]
        for i in range(l - 1, r - 1):
            # Check if there's a previous occurrence within range
            if prev[i] >= l:
                min_distance = min(min_distance, i - prev[i])
            # Check if there's a next occurrence within range
            if next_pos[i] <= r:
                min_distance = min(min_distance, next_pos[i] - i)

        if min_distance == float('inf'):
            output.append("-1")
        else:
            output.append(str(min_distance))

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    solve()
"}

