import sys

def contains_substring(t, s):
    """
    Check if string t contains s as a substring (considering wrap-around).
    """
    n = len(t)
    m = len(s)

    # Check all cyclic substrings of length m
    for i in range(n):
        substring = ''
        for j in range(m):
            pos = (i + j) % n
            substring += t[pos]
        if substring == s:
            return True
    return False

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    count = 0
    # Generate all binary strings of length n
    for mask in range(2 ** n):
        t = ''
        for i in range(n):
            if mask & (1 << i):
                t += '1'
            else:
                t += '0'

        if contains_substring(t, s):
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
