n, p = map(int, input().split())

# Build graph: adjacency list
graph = [[] for _ in range(n + 1)]
for _ in range(p):
    a, b, d = map(int, input().split())
    graph[a].append((b, d))

# Find tanks: has outgoing pipe and no incoming pipe
# A house has no incoming pipe if it's not in any graph[j][0] for j != i
has_incoming = [False] * (n + 1)
for j in range(1, n + 1):
    if len(graph[j]) > 0:
        for next_house, _ in graph[j]:
            has_incoming[next_house] = True

tanks = []
for i in range(1, n + 1):
    if len(graph[i]) > 0 and not has_incoming[i]:
        tanks.append(i)

# Find taps: has incoming pipe and no outgoing pipe
# A house has no outgoing pipe if len(graph[i]) == 0
# A house has incoming pipe if has_incoming[i] is True

taps = []
for i in range(1, n + 1):
    if len(graph[i]) == 0 and has_incoming[i]:
        taps.append(i)

tap_indices = {tap: idx for idx, tap in enumerate(taps)}

# For each tank, trace the path
results = []
for tank in tanks:
    current = tank
    min_diameter = float('inf')
    path = []
    while current is not None:
        next_house = None
        if graph[current]:
            next_house, diameter = graph[current][0]
            min_diameter = min(min_diameter, diameter)
        path.append(current)
        current = next_house

    tap = path[-1]
    if tap in tap_indices:
        results.append((tank, tap, min_diameter))

# Sort by tank
results.sort()

# Output
print(len(results))
for tank, tap, diameter in results:
    print(tank, tap, diameter)
