def solve():
    t, k = map(int, input().split())

    max_b = 0
    test_cases = []
    for _ in range(t):
        a, b = map(int, input().split())
        test_cases.append((a, b))
        max_b = max(max_b, b)

    # Precompute ways(n) for 0 ≤ n ≤ max_b
    ways = [0] * (max_b + 1)
    ways[0] = 1

    for n in range(1, max_b + 1):
        if n < k:
            ways[n] = 1
        else:
            ways[n] = (ways[n-1] + ways[n-k]) % MOD

    # Compute prefix sums
    prefix = [0] * (max_b + 1)
    for n in range(1, max_b + 1):
        prefix[n] = (prefix[n-1] + ways[n]) % MOD

    # Process test cases
    for a, b in test_cases:
        if a == 0:
            result = prefix[b]
        else:
            result = (prefix[b] - prefix[a-1]) % MOD
        print(result)

solve()
