def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def solve():
    n = int(input())
    points = []
    for _ in range(n):
        x, y = map(int, input().split())
        points.append((x, y))
    s = input().strip()

    # Try both points as potential starting points
    for start_idx in [0, 1]:
        path = [start_idx]
        visited = [False] * n
        visited[start_idx] = True

        for i in range(1, n):
            # Get previous point
            if len(path) == 1:
                # Only one point, can choose any next point
                for j in range(n):
                    if not visited[j]:
                        path.append(j)
                        visited[j] = True
                        break
            else:
                # Get previous point
                prev = path[-2]
                curr = path[-1]

                # Required direction: left if s[i-2] == 'L', right if s[i-2] == 'R'
                required = s[i-2] if i >= 2 else ''

                # Try all possible next points
                next_candidates = []
                for j in range(n):
                    if not visited[j]:
                        # Check if this point gives the required turn
                        if required == 'L':
                            # Cross product should be > 0
                            if cross(points[prev], points[curr], points[j]) > 0:
                                next_candidates.append(j)
                        elif required == 'R':
                            # Cross product should be < 0
                            if cross(points[prev], points[curr], points[j]) < 0:
                                next_candidates.append(j)

                if next_candidates:
                    # Choose the next point greedily
                    path.append(next_candidates[0])
                    visited[next_candidates[0]] = True
                else:
                    # No candidates, backtrack
                    if start_idx == 0:
                        return -1
                    else:
                        return -1

        # Check if we have a valid path
        if len(path) == n and set(path) == set(range(n)):
            print(' '.join(str(p + 1) for p in path))
            return

    return -1

