import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    a.sort()
    # cyclic shift: b[i] = a[(i+1)%n] if i < n
    b = [a[(i+1)%n] for i in range(n)]
    # check condition
    ok = True
    for mask in range(1, 1 << n):
        # proper subset: not all zeros, not all ones
        if bin(mask).count('1') == 0 or bin(mask).count('1') == n:
            continue
        s = 0
        t = 0
        for i in range(n):
            if mask & (1 << i):
                s += a[i]
                t += b[i]
        if s == t:
            ok = False
            break
    if not ok:
        print(-1)
    else:
        print(' '.join(map(str, b)))

if __name__ == '__main__':
    solve()
