    gcd_candidates = [d for d, f in freq.items() if f == 2]

    # Try all gcd candidates
    for gcd_candidate in gcd_candidates:
        # Try all ways to split the remaining numbers into two groups
        remaining = [d for d in divisors if d != gcd_candidate]

        # Try all possible splits
