    for i in range(1, n):
        for j in range(i+1, n):
            part1 = s[:i]
            part2 = s[i:j]
            part3 = s[j:]
            # Try all 6 permutations
            for perm in [[part1, part2, part3],
                         [part1, part3, part2],
                         [part2, part1, part3],
                         [part2, part3, part1],
