def can_make_palindrome(count_0, count_1, length):
    """Check if we can make a palindrome with given 0/1 counts"""
    if length % 2 == 0:
        # Even length: we need even counts of both characters
        return count_0 % 2 == 0 and count_1 % 2 == 0
    else:
        # Odd length: we need one character to appear an odd number of times
        # But we don't need one of each character
        # We just need at least one of at least one character
        return count_0 > 0 or count_1 > 0

Q = int(input())
