    n = int(input())
    total_0 = 0
    total_1 = 0
    strings = []

    for _ in range(n):
        s = input().strip()
        strings.append(s)
        total_0 += s.count('0')
        total_1 += s.count('1')

    palindromic_count = 0

    # Strategy: Make odd-length strings first
    for s in strings:
        if len(s) % 2 == 1:
            if total_0 > 0 or total_1 > 0:
                palindromic_count += 1
                # For odd length, we need 1 of one character
                # We'll use one of whichever character we have
                if total_0 > 0:
                    total_0 -= 1
                else:
                    total_1 -= 1

    # Now try even-length strings
    for s in strings:
        if len(s) % 2 == 0:
            if total_0 % 2 == 0 and total_1 % 2 == 0:
                palindromic_count += 1
                # For even length, we need even counts of both characters
                total_0 -= 2
                total_1 -= 2

    print(palindromic_count)
