def get_doors(char, rotation):
    """Return set of directions ("up", "right", "down", "left") a block can pass through."""
    if rotation == 0:
        # Original directions
        if char == '+': return {"up", "right", "down", "left"}
        if char == '-': return {"right", "left"}
        if char == '|': return {"up", "down"}
        if char == '^': return {"up"}
        if char == '>': return {"right"}
        if char == '<': return {"left"}
        if char == 'v': return {"down"}
        if char == 'L': return {"up", "right", "down"}  # missing left
        if char == 'R': return {"up", "left", "down"}  # missing right
        if char == 'U': return {"right", "down", "left"}  # missing up
        if char == 'D': return {"up", "left", "right"}  # missing down
        if char == '*': return set()
    elif rotation == 1:
        # 90 degrees clockwise (up→right, right→down, down→left, left→up)
        if char == '+': return {"right", "down", "left", "up"}
        if char == '-': return {"left", "right"}  # left=originally up, right=originally down
        if char == '|': return {"up", "right"}  # up=originally left, right=originally right
        if char == '^': return {"left"}  # originally left
        if char == '>': return {"down"}  # originally down
        if char == '<': return {"up"}  # originally up
        if char == 'v': return {"right"}  # originally right
        if char == 'L': return {"down", "left", "right"}  # missing up
        if char == 'R': return {"up", "left", "right"}  # missing down
        if char == 'U': return {"right", "down", "left"}  # missing up? Let me check: originally missing up becomes missing right?
        if char == 'D': return {"up", "left", "right"}  # originally missing down becomes missing left?
        if char == '*': return set()
    elif rotation == 2:
        # 180 degrees clockwise (up→down, right→left)
        if char == '+': return {"down", "left", "up", "right"}
        if char == '-': return {"left", "right"}
        if char == '|': return {"down", "up"}
        if char == '^': return {"down"}
        if char == '>': return {"left"}
        if char == '<': return {"right"}
        if char == 'v': return {"up"}
        if char == 'L': return {"down", "right", "left"}  # missing up becomes missing down?
        if char == 'R': return {"up", "down", "left"}  # missing right becomes missing up?
        if char == 'U': return {"left", "down", "right"}  # missing up becomes missing left?
        if char == 'D': return {"up", "right", "left"}  # missing down becomes missing right?
        if char == '*': return set()
    elif rotation == 3:
        # 270 degrees clockwise (up→left, right→up)
        if char == '+': return {"left", "up", "right", "down"}
        if char == '-': return {"left", "right"}
        if char == '|': return {"down", "left"}  # up=originally left, left=originally up?
        if char == '^': return {"left"}  # originally left
        if char == '>': return {"up"}  # originally up
        if char == '<': return {"down"}  # originally down
        if char == 'v': return {"right"}  # originally right
        if char == 'L': return {"right", "down", "left"}  # missing up becomes missing right?
        if char == 'R': return {"up", "down", "left"}  # missing right becomes missing down?
        if char == 'U': return {"down", "left", "right"}  # missing up becomes missing down?
        if char == 'D': return {"up", "right", "left"}  # missing down becomes missing left?
        if char == '*': return set()
    return set()

# Directions: up, right, down, left
# Map from direction to delta (dx, dy)
directions = {
    "up": (-1, 0),
    "right": (0, 1),
    "down": (1, 0),
    "left": (0, -1)
}

def solve():
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Start and end positions
    xT, yT = map(int, input().split())
    xM, yM = map(int, input().split())

    # Convert to 0-indexed
    start = (xT - 1, yT - 1)
    end = (xM - 1, yM - 1)

    # BFS: (x, y, rotations) -> time
    from collections import deque
    visited = set()
    queue = deque([(start[0], start[1], 0, 0)])  # (x, y, rotations, time)
    visited.add((start[0], start[1], 0))

    # Directions: up, right, down, left
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    while queue:
        x, y, rot, time = queue.popleft()

        # Check if we reached the end
        if (x, y) == end:
            print(time)
            return

        # Try to move to neighboring blocks
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                # Get doors for current position and rotation
                curr_doors = get_doors(grid[x][y], rot)
                # Get doors for neighbor position and rotation
                neighbor_doors = get_doors(grid[nx][ny], rot)

                # Check if both blocks have doors in the opposite direction
                curr_has_door = directions_to_opposite_direction(curr_doors, dx, dy)
                neighbor_has_door = directions_to_opposite_direction(neighbor_doors, -dx, -dy)

                if curr_has_door and neighbor_has_door:
                    if (nx, ny, rot) not in visited:
                        visited.add((nx, ny, rot))
                        queue.append((nx, ny, rot, time + 1))

        # Try to rotate (if not at maximum rotation)
        if rot < 3:
            if (x, y, rot + 1) not in visited:
                visited.add((x, y, rot + 1))
                queue.append((x, y, rot + 1, time + 1))

    # If we've explored everything and didn't find end
    print(-1)

# Helper: check if a block has a door in a specific direction (dx, dy)
def directions_to_opposite_direction(doors, dx, dy):
    """Check if a block has a door in the opposite direction of (dx, dy)."""
    # Map from direction to opposite direction
    opposite = {
        (-1, 0): "up",
        (0, 1): "right",
        (1, 0): "down",
        (0, -1): "left"
    }

    # Get the opposite direction
    opposite_dir = opposite.get((dx, dy), None)

    if opposite_dir is None:
        return False

    return opposite_dir in doors

solve()
