def can_make_palindrome(remaining_zeros, remaining_ones, length, prefer_0):
    """Check if we can make a palindrome with the given remaining characters"""
    if length % 2 == 1:
        # Odd length: we need one character that can be either 0 or 1
        # We need (length-1)//2 of one character
        needed = (length - 1) // 2
        if prefer_0:
            if remaining_zeros >= needed:
                return True, (needed, 1)
            else:
                # Try making it start with 1
                if remaining_ones >= needed:
                    return True, (1, needed)
                else:
                    return False, (0, 0)
        else:
            if remaining_ones >= needed:
                return True, (1, needed)
            else:
                if remaining_zeros >= needed:
                    return True, (needed, 1)
                else:
                    return False, (0, 0)
    else:
        # Even length: need equal numbers of 0 and 1
        half = length // 2
        if remaining_zeros >= half and remaining_ones >= half:
            return True, (half, half)
        return False, (0, 0)

