def extend(s, j, b):
    """Extend state j with character b."""
    if j == len(s):
        return len(s)

    current = s[:j] + b
    l = 0
    while l < min(len(s), len(current)):
        if s[l] == current[l]:
            l += 1
        else:
            break
    return l

def count_no_substring(n, s):
    len_s = len(s)
    dp = [0] * len_s
    dp[0] = 1

    for i in range(n):
        new_dp = [0] * len_s
        for state in range(len_s):
            if dp[state] == 0:
                continue
            for b in ('0', '1'):
                next_state = extend(s, state, b)
                if next_state == len_s:
                    # String contains s, skip
                    continue
                new_dp[next_state] += dp[state]
        dp = new_dp

    total_no_substring = sum(dp)
    return total_no_substring

