# Read input
n, k = map(int, input().split())

# Initialize DP table
MOD = 1000000007
dp = [[0] * (n + 1) for _ in range(k + 1)]

# Base case: sequences of length 1
for x in range(1, n + 1):
    dp[1][x] = 1

# Fill DP table
for length in range(2, k + 1):
    for x in range(1, n + 1):
        # Count sequences of length-1 that end with a divisor of x
        for d in range(1, x + 1):
            if x % d == 0:
                dp[length][x] = (dp[length][x] + dp[length - 1][d]) % MOD

# Answer is sum of sequences of length k ending with any number
answer = sum(dp[k][x] for x in range(1, n + 1)) % MOD
print(answer)
