    a, b, c, d = map(int, input().split())

    # Create a list of all cities
    cities = list(range(1, n + 1))

    # Construct path 1: a -> c -> ... -> d -> b
    path1 = [a, c]
    for city in cities:
        if city != a and city != c:
            path1.append(city)
    path1.append(d)
    path1.append(b)

    # Construct path 2: c -> a -> ... -> d -> b
    path2 = [c, a]
    for city in cities:
        if city != c and city != a:
            path2.append(city)
    path2.append(d)
    path2.append(b)

    # Check if both paths visit all n cities
    if len(set(path1)) != n or len(set(path2)) != n:
        print(-1)
        return

    # Count unique roads using sets
    def count_roads(path):
        roads = set()
        for i in range(len(path) - 1):
            u, v = path[i], path[i + 1]
            if u > v:
                u, v = v, u
            roads.add((u, v))
        return len(roads)

