def count_prime_factor_in_factorial(n, p):
    count = 0
    power = p
    while power <= n:
        count += n // power
        power *= p
    return count


def solve():
    # Read input
    n, b = map(int, input().split())

    # Factorize b
    factors = {}
    i = 2
    temp = b
    while i * i <= temp:
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
        i += 1
    if temp > 1:
        factors[temp] = 1

    # Find minimum floor(count / exponent)
    min_zeros = float('inf')
    for prime, exponent in factors.items():
        count = count_prime_factor_in_factorial(n, prime)
        min_zeros = min(min_zeros, count // exponent)

    print(min_zeros)

solve()
"}

