def note_to_index(note):
    return {
        'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5, 
        'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'B': 10, 'H': 11
    }[note]

notes = input().split()
indices = [note_to_index(note) for note in notes]

# Check all permutations of the 3 notes
from itertools import permutations

found_major = False
found_minor = False

for perm in permutations(indices):
    x, y, z = perm
    # Distance between x and y
    dist_xy = y - x if y >= x else 12 - (x - y)
    # Distance between y and z
    dist_yz = z - y if z >= y else 12 - (y - z)

    if dist_xy == 4 and dist_yz == 3:
        found_major = True
    if dist_xy == 3 and dist_yz == 4:
        found_minor = True

if found_major:
    print("major")
elif found_minor:
    print("minor")
else:
    print("strange")
"}

