import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+n]))

    buses = 0
    current = 0

    for ai in a:
        if ai <= m - current:
            current += ai
        else:
            buses += 1
            current = ai
    if current > 0:
        buses += 1

    print(buses)

if __name__ == "__main__":
    solve()
"}

